sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);

	function TestCase_IsTechnicalUser(vUser, vExpected)
	{
		function TestCase_IsTechnicalUser_CheckResult(vInput,vExpected,vResult)
		{
			return (vExpected == vResult);
		}

		test.TestCase(
			'Function IsTechnicalUser()',
			IsTechnicalUser,
			{
				'User': vUser
			},
			vExpected,
			TestCase_IsTechnicalUser_CheckResult);
	}

	var testdata = new TestDataAPI('ATF.DEVTOOLS');
	var strUserNormal1SysId = testdata.CreateUser('NORMAL1',[],false);
	var strUserTech1SysId = testdata.CreateUser('TECH1',[],true);

	test.Log(GetUserRecord(strUserNormal1SysId));
	test.Log(GetUserRecord(strUserTech1SysId));

	TestCase_IsTechnicalUser(null,false);
	TestCase_IsTechnicalUser('',false);
	TestCase_IsTechnicalUser('test.atf.devtools.normal1',false);
	TestCase_IsTechnicalUser(strUserNormal1SysId,false);
	
	TestCase_IsTechnicalUser('technical.test.atf.devtools.tech1',true);
	TestCase_IsTechnicalUser(strUserTech1SysId,true);

	var strUserTech2SysId = testdata.CreateUser('TECH2',[],true);
	TestCase_IsTechnicalUser(strUserTech2SysId,true);
	RecordSetValue('sys_user',strUserTech2SysId,'identity_type','human');
	TestCase_IsTechnicalUser(strUserTech2SysId,false);
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
